import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { sectionLabels } from './courses';

type Entry = App.Locals['starlightRoute']['sidebar'][number];

/** Gives autogenerated sub-folder groups (e.g. python-advanced/mudrosti) a readable, translated label. */
export const onRequest = defineRouteMiddleware((context) => {
  const route = context.locals.starlightRoute;
  const lang = route.lang?.startsWith('en') ? 'en' : 'sk';

  const relabel = (entries: Entry[]) => {
    for (const entry of entries) {
      if (entry.type !== 'group') continue;
      const label = sectionLabels[entry.label];
      if (label) entry.label = label[lang];
      relabel(entry.entries);
    }
  };

  relabel(route.sidebar);
});
